const input = $steps['trigger-form'].data;
const hotelId = 'HOT-' + Math.floor(1000 + Math.random() * 9000);

const hotelRecord = {
  hotel_id: hotelId,
  name: input.name,
  country: input.country || 'Argentina',
  city: input.city || 'Buenos Aires',
  currency: input.currency || 'USD',
  total_rooms: parseInt(input.total_rooms) || 30,
  base_rate: parseFloat(input.base_rate) || 100.00,
  min_rate: parseFloat(input.min_rate) || 70.00,
  max_rate: parseFloat(input.max_rate) || 300.00,
  created_at: new Date().toISOString()
};

const defaultRules = [
  {
    rule_id: 'RUL-OCC-' + hotelId,
    hotel_id: hotelId,
    rule_type: 'OCCUPANCY_SURGE',
    threshold_min: 80.0,
    threshold_max: 100.0,
    adjustment_type: 'PERCENTAGE',
    adjustment_value: 15.0,
    is_active: true
  }
];

const emailNotification = {
  to: input.manager_email,
  subject: `[Destino Vivo] Bienvenido a Destino Vivo RMS - ${input.name}`,
  body: `Hola ${input.manager_name},\n\nTu hotel '${input.name}' ha sido registrado exitosamente en Destino Vivo.\n\nConfiguración Inicial:\n- Tarifa Base: $${hotelRecord.base_rate} ${hotelRecord.currency}\n- Regla Ocupación: +15% cuando la ocupación supere el 80%\n\nPuedes acceder al dashboard en cualquier momento para ajustar tus reglas.\n\nSaludos,\nEquipo Destino Vivo`
};

return { hotelRecord, defaultRules, emailNotification };
